pub(crate) struct ExportProducer{vector:Option<DocumentVectorJob<'static>>,vector_close:Option<DocumentVectorRetirement<'static>>,view_box:Option<[f64;4]>,bounds:Option<[f64;4]>,bound_at:usize,raster:Option<DocumentRasterJob<'static>>,raster_close:Option<DocumentRasterRetirement<'static>>,read:Option<store::SnapshotRead<DrawingSnapshot>>,read_close:Option<Box<dyn semio_framework_value::ErasedSnapshotRetirement>>,output:ControlledRetirement<OutputOwners>,pub(crate) phase:&'static str,pixel:usize,options:ExportOptions,transparent:bool,complete:bool,closing:bool}
fn extent(document:&DrawingSnapshot,options:ExportOptions)->Result<(u32,u32,f64,f64),Fault>{let(world_width,world_height)=document.artboard.as_ref().map_or((1024.0,1024.0),|board|(board.width,board.height));if ![world_width,world_height].into_iter().all(|n|n.is_finite()&&n>0.0&&n<=1e9){return Err(Fault::from("Invalid PNG artboard extent"));}let width=options.width.unwrap_or(world_width.ceil()as u32);let height=options.height.unwrap_or(world_height.ceil()as u32);if !(1..=16384).contains(&width)||!(1..=16384).contains(&height)||u64::from(width)*u64::from(height)>67108864{return Err(Fault::from("PNG requested pixel extent exceeds capacity"));}Ok((width,height,f64::from(width)/world_width,f64::from(height)/world_height))}
impl ExportProducer{
 pub(crate) fn new(read:store::SnapshotRead<DrawingSnapshot>,options:ExportOptions)->Self{let output=ControlledRetirement::new(OutputOwners{pdf:None,pdf_close:None,svg:None,svg_close:None,paint:None,paint_close:None,painted:None,plan:None,image:None,encoder:None,raw:Some(OwnedSerializerOutput::empty()),failure:None}).unwrap_or_else(|_|unreachable!());Self{vector:None,vector_close:None,view_box:None,bounds:None,bound_at:0,raster:None,raster_close:None,read:Some(read),read_close:None,output,phase:"prepare",pixel:0,options,transparent:options.transparent,complete:false,closing:false}}
 pub(crate) fn pending_source(&self)->Option<&store::SnapshotRead<DrawingSnapshot>>{self.read.as_ref()}
 pub(crate) fn source_authority_matches(&self,generation:u64,revision:[u8;32])->bool{if let Some(job)=&self.vector{job.snapshot_authority_matches(generation,revision)}else if let Some(close)=&self.vector_close{close.snapshot_authority_matches(generation,revision)}else if let Some(job)=&self.raster{job.snapshot_authority_matches(generation,revision)}else if let Some(close)=&self.raster_close{close.snapshot_authority_matches(generation,revision)}else{self.read.as_ref().is_some_and(|read|read.commit_authority_matches(generation,revision))}}
 pub(crate) fn output(&self)->Option<&OwnedSerializerOutput>{self.complete.then(||self.output.original()?.raw.as_ref()).flatten()}
 pub(crate) fn take_output(&mut self)->Option<OwnedSerializerOutput>{if self.complete{self.output.original_mut()?.raw.take()}else{None}}
 fn initialize(&mut self)->Result<(),Fault>{if !["png","svg","pdf"].contains(&self.options.format){return Err(Fault::from("Drawing exports to png, pdf or svg"));}self.view_box=self.read.as_ref().unwrap().get().artboard.as_ref().map(|board|[0.0,0.0,board.width,board.height]);if self.options.format=="png"{let(width,height,x,y)=extent(self.read.as_ref().unwrap().get(),self.options)?;let mut producer=DocumentRasterJob::from_snapshot_read(self.read.take().unwrap(),DocumentSceneLimits::default(),DocumentSceneViewport{width,height,origin:[0.0;2],tolerance:0.01,max_pixels:67108864,max_source_bytes:268439552},DocumentAlgorithmLimits::default());if let Err(error)=producer.set_pixel_scale(x,y){self.raster=Some(producer);return Err(Fault::from(error.to_string()));}self.raster=Some(producer);self.phase="raster";}else{self.vector=Some(DocumentVectorJob::from_snapshot_read(self.read.take().unwrap(),DocumentSceneLimits::default(),DocumentAlgorithmLimits::default()));self.phase="vector-prepare";}Ok(())}
 pub(crate) fn close_demands(&self,body:usize)->Result<semio_framework_value::RetirementDemand,ValueError>{
  if !self.output.terminal_is_empty(){return Ok(semio_framework_value::RetirementDemand{copy_bytes:self.output.next_copy_byte_demand()?,capacity_bytes:self.output.next_capacity_byte_demand(body)?,release_bytes:self.output.next_release_byte_demand()?,depth:self.output.next_depth_demand()?});}
  if let Some(read)=&self.read_close{return store::artifact_retirement_box_demands(read,body);}
  if self.read.is_some(){return store::artifact_retirement_owned_birth_demands(&self.read);}
  if let Some(close)=&self.vector_close{return Ok(semio_framework_value::RetirementDemand{copy_bytes:close.next_copy_byte_demand()?,capacity_bytes:close.next_capacity_byte_demand(body)?,release_bytes:close.next_release_byte_demand()?,depth:close.next_depth_demand()?});}
  if let Some(close)=&self.raster_close{return Ok(semio_framework_value::RetirementDemand{copy_bytes:close.next_copy_byte_demand()?,capacity_bytes:close.next_capacity_byte_demand(body)?,release_bytes:close.next_release_byte_demand()?,depth:close.next_depth_demand()?});}
  Ok(Default::default())
 }
 pub(crate) fn advance(&mut self,generation:u64,revision:[u8;32],cx:&mut semio_framework_job::StepContext<'_>)->Result<bool,Fault>{
  if self.closing||cx.is_cancelled(){return Err(Fault::from("Drawing export cancelled or terminal"));}
  if !self.source_authority_matches(generation,revision){return Err(Fault::from("Drawing export source authority changed"));}
  if self.complete{return Ok(true);}if cx.should_yield(){return Ok(false);}
  if self.phase=="prepare"{self.initialize()?;cx.consume_fuel(1);return Ok(false);}  let owners=self.output.original_mut().ok_or_else(||Fault::from("Drawing export retirement started"))?;
  if let Some(error)=&owners.failure{return Err(Fault::from(error.as_str()));}
  while !cx.should_yield(){
   if cx.is_cancelled(){return Err(Fault::from("Drawing export cancelled"));}cx.set_stage(self.phase);
   match self.phase {
    "vector-prepare"=>{let progress=self.vector.as_mut().unwrap().advance(1).map_err(|error|Fault::from(error.to_string()))?;cx.consume_fuel(1);if !progress.done{continue;}let(close,plan)=self.vector.take().unwrap().into_retirement();self.vector_close=Some(close);let plan=plan.unwrap();if let Some(view_box)=self.view_box{if self.options.format=="pdf"{owners.pdf=Some(PdfWriteJob::new(plan,PdfWriteLimits{view_box,max_output_bytes:RAW_OUTPUT_LIMIT,max_work:1000000000}));self.phase="pdf-write";}else{owners.svg=Some(SvgWriteJob::new(plan,SvgWriteLimits{view_box,max_output_bytes:RAW_OUTPUT_LIMIT,max_work:1000000000}));self.phase="svg-write";}}else{owners.paint=Some(ScenePaintJob::new(plan,0.005,PaintedSceneLimits{max_nodes:1024,max_segments:65536,max_points:262144,max_contours:65536,max_work:1000000000}));self.phase="vector-paint";}},
    "vector-paint"=>{let progress=owners.paint.as_mut().unwrap().advance(1).map_err(Fault::from)?;cx.consume_fuel(1);if progress.done{let(close,painted)=owners.paint.take().unwrap().into_retirement();owners.paint_close=Some(close);owners.painted=painted;self.phase="vector-bounds";}},
    "vector-bounds"=>{let painted=owners.painted.as_mut().unwrap();if self.bound_at<painted.geometry.len(){if painted.plan.nodes[self.bound_at].visible{if let Some(b)=painted.geometry[self.bound_at].bounds.or(painted.geometry[self.bound_at].geometry_bounds){self.bounds=Some(self.bounds.map_or(b,|a|[a[0].min(b[0]),a[1].min(b[1]),a[2].max(b[2]),a[3].max(b[3])]));}}self.bound_at+=1;cx.consume_fuel(1);continue;}let[x1,y1,x2,y2]=self.bounds.unwrap_or([0.0,0.0,1024.0,768.0]);let plan=std::mem::take(&mut painted.plan);let view_box=[x1,y1,(x2-x1).max(1.0),(y2-y1).max(1.0)];if self.options.format=="pdf"{owners.pdf=Some(PdfWriteJob::new(plan,PdfWriteLimits{view_box,max_output_bytes:RAW_OUTPUT_LIMIT,max_work:1000000000}));self.phase="pdf-write";}else{owners.svg=Some(SvgWriteJob::new(plan,SvgWriteLimits{view_box,max_output_bytes:RAW_OUTPUT_LIMIT,max_work:1000000000}));self.phase="svg-write";}cx.consume_fuel(1);},
    "pdf-write"=>{let progress=owners.pdf.as_mut().unwrap().advance(1).map_err(Fault::from)?;cx.consume_fuel(1);if progress.done{let(close,pages)=owners.pdf.take().unwrap().into_retirement();owners.pdf_close=Some(close);owners.raw.as_mut().unwrap().pages=pages.unwrap();self.phase="output";}},
    "svg-write"=>{let progress=owners.svg.as_mut().unwrap().advance(1).map_err(Fault::from)?;cx.consume_fuel(1);if progress.done{let(close,pages)=owners.svg.take().unwrap().into_retirement();owners.svg_close=Some(close);owners.raw.as_mut().unwrap().pages=pages.unwrap();self.phase="output";}},
    "raster"=>{let progress=self.raster.as_mut().unwrap().advance(1).map_err(|error|Fault::from(error.to_string()))?;cx.consume_fuel(1);if !progress.done{continue;}let(close,image)=self.raster.take().unwrap().into_retirement();self.raster_close=Some(close);owners.image=image;self.phase="background";},
    "background"=>{if !self.transparent&&self.pixel<owners.image.as_ref().unwrap().pixels.len(){let image=owners.image.as_mut().unwrap();let at=self.pixel;let alpha=f64::from(image.pixels[at+3]);for channel in 0..3{image.pixels[at+channel]=(f64::from(image.pixels[at+channel])*alpha/255.0+255.0-alpha).round()as u8;}image.pixels[at+3]=255;self.pixel+=4;cx.consume_fuel(1);continue;}owners.encoder=Some(match semio_framework_pixels::png_encoding::PngEncodeJob::with_maximum_bytes(owners.image.take().unwrap(),RAW_OUTPUT_LIMIT){Ok(encoder)=>encoder,Err((error,image))=>{owners.image=Some(image);return Err(Fault::from(error.to_string()));}});self.phase="encode";cx.consume_fuel(1);},
    "encode"=>{let encoder=owners.encoder.as_mut().unwrap();let progress=encoder.advance().map_err(|error|Fault::from(error.to_string()))?;cx.consume_fuel(1);if progress.done{owners.raw.as_mut().unwrap().contiguous=encoder.take_result().map_err(|error|Fault::from(error.to_string()))?.data;self.phase="output";}},
    "output"=>{self.complete=true;cx.consume_fuel(1);return Ok(true);},
    _=>return Err(Fault::from("Drawing export stage is invalid")),
   }
  }
  Ok(false)
 }
 pub(crate) fn begin_close(&mut self){self.closing=true;if let Some(job)=self.vector.take(){let(close,plan)=job.into_retirement();self.vector_close=Some(close);if let Some(plan)=plan{if let Some(output)=self.output.original_mut(){output.plan=Some(plan);}}}if let Some(job)=self.raster.take(){let(close,image)=job.into_retirement();self.raster_close=Some(close);if let Some(image)=image{if let Some(output)=self.output.original_mut(){output.image=Some(image);}}}}
 pub(crate) fn close_step(&mut self,grant:RetainedCloneGrant)->semio_framework_job::InteractiveJobCloseStep{
  use semio_framework_job::InteractiveJobCloseStep;if !self.closing{return InteractiveJobCloseStep::Blocked;}
  if !self.output.terminal_is_empty(){return match self.output.step(grant){Ok(step)=>InteractiveJobCloseStep::Pending{progress:step.progress()},Err(error)=>InteractiveJobCloseStep::Refused(error.kind)};}
  if self.read_close.is_some()||self.read.is_some(){let step=if self.read_close.is_some(){store::artifact_retirement_box_close_step(&mut self.read_close,grant)}else{store::artifact_retirement_admit_owned(&mut self.read,&mut self.read_close,grant)};return match step{Ok(step)=>InteractiveJobCloseStep::Pending{progress:step.progress()},Err(error)=>InteractiveJobCloseStep::Refused(error.kind)};}
  if let Some(close)=&mut self.vector_close{if grant.maximum_items==0||grant.maximum_depth==0{return InteractiveJobCloseStep::Blocked;}if let Some(read)=close.take_snapshot_read(){self.read=Some(read);return InteractiveJobCloseStep::Pending{progress:RetainedCloneProgress{copied_items:1,..Default::default()}};}return match close.close_step(grant){Ok(step)=>{let progress=step.progress();if close.terminal_is_empty(){self.vector_close=None;}InteractiveJobCloseStep::Pending{progress}},Err(error)=>InteractiveJobCloseStep::Refused(error.kind)};}
  if let Some(close)=&mut self.raster_close{
   if grant.maximum_items==0||grant.maximum_depth==0{return InteractiveJobCloseStep::Blocked;}
   if let Some(read)=close.take_snapshot_read(){self.read=Some(read);return InteractiveJobCloseStep::Pending{progress:RetainedCloneProgress{copied_items:1,..Default::default()}};}
   return match close.close_step(grant){Ok(step)=>{let progress=step.progress();if close.terminal_is_empty(){self.raster_close=None;}InteractiveJobCloseStep::Pending{progress}},Err(error)=>InteractiveJobCloseStep::Refused(error.kind)};
  }
  
  InteractiveJobCloseStep::Complete{progress:Default::default()}
 }
 pub(crate) fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(0)?.copy_bytes)}
 pub(crate) fn next_close_capacity_byte_demand(&self,body:usize)->Result<usize,ValueError>{Ok(self.close_demands(body)?.capacity_bytes)}
 pub(crate) fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(0)?.release_bytes)}
 pub(crate) fn next_close_depth_demand(&self)->Result<usize,ValueError>{Ok(self.close_demands(0)?.depth)}
 pub(crate) fn terminal_is_empty(&self)->bool{self.closing&&self.vector.is_none()&&self.vector_close.is_none()&&self.raster.is_none()&&self.raster_close.is_none()&&self.read.is_none()&&self.read_close.is_none()&&self.output.terminal_is_empty()}
}

