fn serializer_options(request:&OwnedSerializerRequest,format:&'static str)->Result<ExportOptions,ValueError>{let invalid=||ValueError::literal(ValueRefusalKind::InvalidValue,"Drawing serializer options must be bounded width, height and transparency");let mut result=ExportOptions{format,width:None,height:None,transparent:true};if matches!(request.options,DslValue::Null){return Ok(result);}let entries=request.options.as_object().filter(|entries|entries.len()<=3).ok_or_else(invalid)?;let mut seen=0u8;for(key,value)in entries{let mask=match key.as_str(){"width"=>1,"height"=>2,"transparent"=>4,_=>return Err(invalid())};if seen&mask!=0{return Err(invalid());}seen|=mask;match key.as_str(){"width"|"height"=>{let n=value.as_u64().filter(|n|(1..=16384).contains(n)).ok_or_else(invalid)?as u32;if mask==1{result.width=Some(n);}else{result.height=Some(n);}},_=>result.transparent=value.as_bool().ok_or_else(invalid)?}}Ok(result)}
