fn serializer_admit(request:OwnedSerializerRequest,grant:RetainedCloneGrant,format:&'static str)->Result<OwnedSerializerAdmission,OwnedSerializerRefusal>{let refusal=|error,request|OwnedSerializerRefusal{error,request,progress:Default::default()};let demand=match serializer_demand(&request,format){Ok(demand)=>demand,Err(error)=>return Err(refusal(error,request))};let progress=match demand.admit(grant){Ok(progress)=>progress,Err(error)=>return Err(refusal(error,request))};let options=serializer_options(&request,format).unwrap_or_else(|_|unreachable!());let OwnedSerializerRequest{source,route,generation,revision,options:original_options,children}=request;let read=match source.try_into_typed::<DrawingSnapshot>(){Ok(read)=>read,Err(source)=>return Err(refusal(ValueError::literal(ValueRefusalKind::InvariantViolated,"Drawing serializer read type changed"),OwnedSerializerRequest{source,route,generation,revision,options:original_options,children}))};let layout=std::alloc::Layout::new::<DrawingOwnedSerializerJob>();let pointer=unsafe{std::alloc::alloc(layout)}.cast::<DrawingOwnedSerializerJob>();if pointer.is_null(){return Err(refusal(ValueError::literal(ValueRefusalKind::OwnershipLimit,"Drawing serializer frame allocation refused"),OwnedSerializerRequest{source:read.into_erased(),route,generation,revision,options:original_options,children}));}let metadata=ControlledRetirement::new(SerializerMetadata{route,options:original_options,failure:None}).unwrap_or_else(|_|unreachable!());let job=DrawingOwnedSerializerJob{producer:ExportProducer::new(read,options),metadata,generation,revision,finished:false,closing:false,cancelled:false,failed:false};unsafe{pointer.write(job);}Ok(OwnedSerializerAdmission{job:unsafe{Box::from_raw(pointer)},progress})}
fn png_demand(request:&OwnedSerializerRequest)->Result<RetainedCloneBirthDemand,ValueError>{serializer_demand(request,"png")}
